import struct
import hashlib
import hmac
import os
from typing import Optional, Tuple

# Secure message framing protocol implementation
# Frame format: [4-byte length][1-byte type][payload][32-byte HMAC]

FRAME_HEADER_SIZE = 5
HMAC_SIZE = 32
MAX_PAYLOAD_SIZE = 65536

class SecureChannel:
    def __init__(self, shared_secret: bytes):
        self.shared_secret = shared_secret
        self.sequence_number = 0
        self.recv_buffer = bytearray()
        self.authenticated = False
        self.session_key: Optional[bytes] = None
        self._pending_fragments: dict = {}
        self._fragment_sizes: dict = {}

    def _derive_key(self, nonce: bytes) -> bytes:
        return hashlib.pbkdf2_hmac('sha256', self.shared_secret, nonce, 100000)

    def _compute_mac(self, data: bytes) -> bytes:
        key = self.session_key if self.session_key else self.shared_secret
        return hmac.new(key, data, hashlib.sha256).digest()

    def _verify_mac(self, data: bytes, expected_mac: bytes) -> bool:
        key = self.session_key if self.session_key else self.shared_secret
        computed = hmac.new(key, data, hashlib.sha256).digest()
        return hmac.compare_digest(computed, expected_mac)

    def initiate_handshake(self) -> bytes:
        nonce = os.urandom(32)
        self.session_key = self._derive_key(nonce)
        frame = self._build_frame(0x01, nonce)
        return frame

    def _build_frame(self, msg_type: int, payload: bytes) -> bytes:
        length = len(payload) + HMAC_SIZE
        header = struct.pack('>IB', length, msg_type)
        mac = self._compute_mac(header + payload)
        return header + payload + mac

    def receive_data(self, data: bytes) -> list:
        self.recv_buffer.extend(data)
        messages = []
        while len(self.recv_buffer) >= FRAME_HEADER_SIZE:
            frame_length = struct.unpack('>I', self.recv_buffer[0:4])[0]
            msg_type = self.recv_buffer[4]

            total_frame_size = FRAME_HEADER_SIZE + frame_length
            if len(self.recv_buffer) < total_frame_size:
                break

            frame_data = bytes(self.recv_buffer[FRAME_HEADER_SIZE:total_frame_size])
            del self.recv_buffer[:total_frame_size]

            msg = self._process_frame(msg_type, frame_data)
            if msg is not None:
                messages.append(msg)

        return messages

    def _process_frame(self, msg_type: int, frame_data: bytes) -> Optional[bytes]:
        if len(frame_data) < HMAC_SIZE:
            return None

        payload = frame_data[:-HMAC_SIZE]
        mac = frame_data[-HMAC_SIZE:]

        header = struct.pack('>IB', len(frame_data), msg_type)
        if not self._verify_mac(header + payload, mac):
            return None

        if msg_type == 0x01:
            return self._handle_handshake(payload)
        elif msg_type == 0x02:
            return self._handle_message(payload)
        elif msg_type == 0x03:
            return self._handle_fragment(payload)
        return None

    def _handle_handshake(self, payload: bytes) -> Optional[bytes]:
        if len(payload) != 32:
            return None
        self.session_key = self._derive_key(payload)
        self.authenticated = True
        return b'HANDSHAKE_OK'

    def _handle_message(self, payload: bytes) -> Optional[bytes]:
        if not self.authenticated:
            return None
        return payload

    def _handle_fragment(self, payload: bytes) -> Optional[bytes]:
        """Handle fragmented messages.
        Fragment header: [2-byte stream_id][2-byte fragment_index][2-byte total_fragments][2-byte fragment_size]
        """
        if not self.authenticated:
            return None
        if len(payload) < 8:
            return None

        stream_id, frag_idx, total_frags, frag_size = struct.unpack('>HHHH', payload[:8])
        fragment_data = payload[8:]

        if total_frags == 0 or total_frags > 256:
            return None
        if frag_idx >= total_frags:
            return None

        # Calculate expected total reassembled size
        # This validates that the total size won't exceed our limits
        expected_total = frag_size * total_frags

        # Vulnerability: frag_size is uint16 (max 65535), total_frags is uint16 (max 256 after check)
        # But expected_total is computed as Python int, so no overflow here.
        # The REAL issue: we use frag_size to validate fragment_data length
        # but frag_size can be 0, making the check below pass vacuously

        if expected_total > MAX_PAYLOAD_SIZE * 4:
            return None

        # BUG: This check uses subtraction that can produce unexpected results
        # when frag_size equals len(fragment_data) + 1 due to off-by-one
        # The check should be: len(fragment_data) != frag_size
        # Instead it checks if the DIFFERENCE is less than or equal to 0
        # using unsigned-style comparison via masking
        size_diff = (len(fragment_data) - frag_size) & 0xFFFFFFFF
        if size_diff > 0x7FFFFFFF:  # Treats as "negative" = fragment_data shorter than declared
            return None  # Reject if fragment_data is SHORTER than declared size

        # But if fragment_data is LONGER than frag_size, size_diff is small positive
        # and we proceed, reading only frag_size bytes from fragment_data
        # This seems safe... BUT:

        if stream_id not in self._pending_fragments:
            self._pending_fragments[stream_id] = {}
            self._fragment_sizes[stream_id] = frag_size

        # Store the fragment - uses declared frag_size, not actual data length
        self._pending_fragments[stream_id][frag_idx] = fragment_data[:frag_size]

        # Check if all fragments received
        if len(self._pending_fragments[stream_id]) == total_frags:
            # Reassemble
            reassembled = bytearray()
            for i in range(total_frags):
                if i not in self._pending_fragments[stream_id]:
                    del self._pending_fragments[stream_id]
                    del self._fragment_sizes[stream_id]
                    return None
                reassembled.extend(self._pending_fragments[stream_id][i])

            del self._pending_fragments[stream_id]
            del self._fragment_sizes[stream_id]
            return bytes(reassembled)

        return None

    def send_fragmented(self, data: bytes, stream_id: int, frag_size: int = 1024) -> list:
        if frag_size <= 0:
            frag_size = 1024

        fragments = []
        total_frags = (len(data) + frag_size - 1) // frag_size

        for i in range(total_frags):
            chunk = data[i*frag_size:(i+1)*frag_size]
            header = struct.pack('>HHHH', stream_id, i, total_frags, frag_size)
            frame = self._build_frame(0x03, header + chunk)
            fragments.append(frame)

        return fragments
